<script setup lang="ts">
import { Head, Link, useForm, router } from '@inertiajs/vue3';
import { watch, ref } from 'vue';
import AthletePicker from '../../Components/AthletePicker.vue';
import RolePermissions from '../../Components/RolePermissions.vue';
import AppLayout from '../../Layouts/AppLayout.vue';
interface Athlete { id:number; first_name:string; last_name:string; email?:string }
interface Race { id:number; name:string; event_date:string }
interface User { id:number; name:string; email:string; role:'admin'|'organizer'|'athlete'; is_active:boolean; athlete_id?:number; athlete?:Athlete; races:Race[] }
const props = defineProps<{ users:{data:User[];current_page:number;last_page:number;prev_page_url:string|null;next_page_url:string|null;total:number}; filters:{q:string}; races:Race[] }>();
const search=ref(props.filters.q);
const searchUsers=()=>router.get('/users',{q:search.value},{preserveState:true,preserveScroll:true});
const form = useForm({name:'',email:'',password:'',role:'organizer',athlete_id:null as number|null,race_ids:[] as number[]});
watch(() => form.role, role => { if(role!=='athlete') form.athlete_id=null; if(role!=='organizer') form.race_ids=[]; });
const submit = () => form.post('/users',{preserveScroll:true,onSuccess:()=>form.reset()});

</script>
<template><Head title="Users"/><AppLayout title="Users & access"><p class="mb-5 muted">Create accounts or edit a user’s details, role, race access and active status.</p><div class="grid gap-5 xl:grid-cols-[1fr_420px]"><section class="panel overflow-hidden"><div class="border-b border-slate-800 p-4 font-bold">Accounts · {{ users.total }}</div><form @submit.prevent="searchUsers" class="flex gap-2 p-4"><input v-model="search" class="field" aria-label="Search accounts" placeholder="Name or email"><button class="btn-secondary">Search</button></form><div class="divide-y divide-slate-800"><div v-for="user in users.data" :key="user.id" class="flex items-start gap-4 p-4"><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><span class="font-semibold">{{ user.name }}</span><span class="badge">{{ user.role }}</span><span v-if="!user.is_active" class="badge !border-red-500/30 !text-red-300">disabled</span></div><div class="muted text-sm">{{ user.email }}</div><div v-if="user.athlete" class="mt-1 text-xs text-slate-400">Athlete: {{ user.athlete.first_name }} {{ user.athlete.last_name }}</div><div v-if="user.races?.length" class="mt-1 text-xs text-slate-400">Races: {{ user.races.map(r=>r.name).join(', ') }}</div></div><Link :href="`/users/${user.id}/edit`" class="btn-secondary !min-h-9 !px-3 !py-1.5 text-sm">Edit user</Link></div></div><nav aria-label="Account pages" class="flex items-center gap-3 p-4"><Link v-if="users.prev_page_url" :href="users.prev_page_url" class="btn-secondary" preserve-state>Previous</Link><span>Page {{ users.current_page }} of {{ users.last_page }}</span><Link v-if="users.next_page_url" :href="users.next_page_url" class="btn-secondary" preserve-state>Next</Link></nav></section><form class="panel-pad h-fit" @submit.prevent="submit"><h2 class="mb-4 text-lg font-bold">Create account</h2><div class="space-y-3"><div><label class="label">Name</label><input v-model="form.name" class="field" required></div><div><label class="label">Email</label><input v-model="form.email" type="email" class="field" required></div><div><label class="label">Temporary password</label><input v-model="form.password" type="password" class="field" minlength="12" required><p class="mt-1 text-xs muted">At least 12 characters.</p></div><div><label class="label">Role</label><select v-model="form.role" class="field"><option value="organizer">Organizer</option><option value="athlete">Athlete</option><option value="admin">Administrator</option></select></div><RolePermissions :role="form.role"/><AthletePicker v-if="form.role==='athlete'" v-model="form.athlete_id"/><div v-if="form.role==='organizer'"><label class="label">Race access</label><div class="max-h-48 space-y-2 overflow-auto rounded-xl border border-slate-800 p-3"><label v-for="race in races" :key="race.id" class="flex gap-2 text-sm"><input v-model="form.race_ids" type="checkbox" :value="race.id"> <span>{{ race.name }}</span></label></div></div></div><p v-if="Object.keys(form.errors).length" class="mt-3 text-sm text-red-300">{{ Object.values(form.errors)[0] }}</p><button class="btn-primary mt-5 w-full" :disabled="form.processing">Create account</button></form></div></AppLayout></template>
